import { useEffect, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { customFetch } from "@workspace/api-client-react";
import { Loader2 } from "lucide-react";
import { BRAND_MAX, type Brand } from "@/lib/branding";
import { issueRefusal } from "@/lib/github-issues";

/**
 * Settings → Report branding: the name PDFs and shared reports carry as "prepared by", and whether they keep a small
 * "generated by SecScan" credit. The server decides what a name may be; the page only shows what it said.
 */
export function BrandingSection() {
  const queryClient = useQueryClient();
  const current = useQuery({
    queryKey: ["report-branding"],
    queryFn: () => customFetch<{ brand: Brand | null; max: number }>("/api/account/branding"),
  });
  const [name, setName] = useState("");
  const [poweredBy, setPoweredBy] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    if (!current.data) return;
    setName(current.data.brand?.name ?? "");
    setPoweredBy(current.data.brand?.poweredBy ?? true);
  }, [current.data]);

  async function save(e: React.FormEvent) {
    e.preventDefault();
    setBusy(true);
    setError(null);
    setSaved(false);
    try {
      await customFetch("/api/account/branding", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: name.trim() === "" ? null : name.trim(), poweredBy }),
      });
      await queryClient.invalidateQueries({ queryKey: ["report-branding"] });
      setSaved(true);
    } catch (err) {
      setError(issueRefusal(err));
    } finally {
      setBusy(false);
    }
  }

  if (current.isLoading) return <Loader2 className="w-4 h-4 animate-spin text-muted-foreground" />;

  return (
    <form onSubmit={save} className="space-y-3">
      <label className="block text-sm">
        <span className="block mb-1 text-muted-foreground">Business or team name</span>
        <input
          value={name}
          onChange={(e) => { setName(e.target.value); setSaved(false); }}
          maxLength={BRAND_MAX}
          placeholder="Acme Security"
          autoComplete="organization"
          className="w-full rounded-lg bg-black/30 border border-white/10 px-3 py-2"
        />
      </label>
      <div className="flex items-center justify-between gap-4">
        <span className="text-sm">Keep a small “generated by SecScan” credit</span>
        <button
          type="button"
          role="switch"
          aria-checked={poweredBy}
          aria-label="Keep a small generated by SecScan credit"
          onClick={() => { setPoweredBy(!poweredBy); setSaved(false); }}
          className={`w-11 h-6 rounded-full border transition-colors shrink-0 ${poweredBy ? "bg-primary border-primary" : "bg-secondary border-white/10"}`}
        >
          <span className={`block w-4 h-4 rounded-full bg-white transition-transform mx-1 ${poweredBy ? "translate-x-5" : ""}`} />
        </button>
      </div>
      <p className="text-xs text-muted-foreground">
        {name.trim() === ""
          ? "Leave the name empty to keep SecScan's own branding."
          : poweredBy
            ? `PDFs say “Prepared by ${name.trim()}” with a small SecScan credit. Shared reports do the same.`
            : `PDFs and shared reports say “Prepared by ${name.trim()}” and no longer carry SecScan's own line or its “Scan your own site” button.`}
      </p>
      {error && <p role="alert" className="text-sm text-red-400">{error}</p>}
      <div className="flex items-center gap-3">
        <button type="submit" disabled={busy} className="px-4 py-2 rounded-lg bg-primary text-primary-foreground text-sm font-semibold disabled:opacity-60 inline-flex items-center gap-2">
          {busy && <Loader2 className="w-4 h-4 animate-spin" />} Save branding
        </button>
        {saved && <span role="status" className="text-sm text-green-400">Saved.</span>}
      </div>
    </form>
  );
}
